#include <bits/stdc++.h>
using namespace std;

// Codeforces 2103C - Median Splits
// Topic: 33. Binary Search

bool check(long long mid, const vector<long long>& a, int k) {
    // Greedy feasibility check: evaluate if answer <= mid is achievable
    long long current = 0;
    int count = 1;
    for (long long x : a) {
        if (x > mid) return false;
        if (current + x > mid) {
            count++;
            current = x;
        } else {
            current += x;
        }
    }
    return count <= k;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<long long> a(n);
    long long low = 0, high = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        low = max(low, a[i]);
        high += a[i];
    }

    long long ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (check(mid, a, k)) {
            ans = mid;
            high = mid - 1; // Try finding a smaller valid bound
        } else {
            low = mid + 1;  // Infeasible, increase bound
        }
    }

    cout << ans << "\n";
    return 0;
}
